    private fun resync(signalId: UInt) {
        core.observe(handle, signalId, false)
        core.observe(handle, signalId, true)
    }

    companion object {
        /** A store with every counter at zero and [`ROWS`] rows numbered from 1. */
        fun create(ctx: UndraCore = UndraCore.shared): Bench {
            val handle = ctx.construct(UndraIds.Objects.Bench.TYPE_ID, UndraIds.Objects.Bench.NEW, ByteArray(0))
            return Bench(ctx, handle)
        }
    }
}

/** A list of [`LIST_LEN`] items with operations that change one item at a time. */
class BigList private constructor(core: UndraCore, handle: Long) : UndraStore(core, handle) {
    private val _items: MutableStateFlow<List<Item>> = signal(emptyList())
    val items: StateFlow<List<Item>> = _items.asStateFlow()
    private val _count: MutableStateFlow<UInt> = signal(0u)
    /** Computed by the core; read-only. */
    val count: StateFlow<UInt> = _count.asStateFlow()

    init {
        core.observe(handle, UInt.MAX_VALUE, true)
    }

    /** A list of [`LIST_LEN`] items numbered from 1. */
    constructor(ctx: UndraCore = UndraCore.shared) : this(
        ctx,
        ctx.construct(UndraIds.Objects.BigList.TYPE_ID, UndraIds.Objects.BigList.NEW, ByteArray(0)),
    )

    /**
     * Inserts a new row with `label` so that it ends at `index` (`index == len` appends), and
     * returns its identity. One keyed `Insert`.
     * @throws ListError
     */
    fun insertAt(index: UInt, label: String): UInt {
        val w = UndraWriter()
        w.writeU32(index)
        w.writeStr(label)
        val body = try {
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.BigList.INSERT_AT),
                UndraIds.Objects.BigList.INSERT_AT,
                w.toByteArray(),
            )
        } catch (e: UndraReplyException) {
            throw ListError.fromReply(e)
        }
        return Codecs.u32.decodeAll(body)
    }

    /**
     * Moves the row at `from` so that it ends at `to`. One keyed `Move`.
     * @throws ListError
     */
    fun moveItem(from: UInt, to: UInt) {
        val w = UndraWriter()
        w.writeU32(from)
        w.writeU32(to)
        try {
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.BigList.MOVE_ITEM),
                UndraIds.Objects.BigList.MOVE_ITEM,
                w.toByteArray(),
            )
        } catch (e: UndraReplyException) {
            throw ListError.fromReply(e)
        }
    }

    /**
     * Removes the row at `index`. One keyed `Remove`.
     * @throws ListError
     */
    fun removeAt(index: UInt) {
        val w = UndraWriter()
        w.writeU32(index)
        try {
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.BigList.REMOVE_AT),
                UndraIds.Objects.BigList.REMOVE_AT,
                w.toByteArray(),
            )
        } catch (e: UndraReplyException) {
            throw ListError.fromReply(e)
        }
    }

    /**
     * Replaces the list with a fresh one of [`LIST_LEN`] items. The platform receives the keyed
     * patch that turns the old list into the new one (a full value if they have little in
     * common).
     */
    fun reset() {
        this.core.callSync(
            CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.BigList.RESET),
            UndraIds.Objects.BigList.RESET,
            ByteArray(0),
        )
    }

    /**
     * Changes the label of the row at `index` and bumps its version. One keyed `Update`.
     * @throws ListError
     */
    fun updateAt(index: UInt, label: String) {
        val w = UndraWriter()
        w.writeU32(index)
        w.writeStr(label)
        try {
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.BigList.UPDATE_AT),
                UndraIds.Objects.BigList.UPDATE_AT,
                w.toByteArray(),
            )
        } catch (e: UndraReplyException) {
            throw ListError.fromReply(e)
        }
    }

    override fun apply(signalId: UInt, op: ChangeOp, reader: UndraReader) {
        when (signalId) {
            0u -> {
                if (op == ChangeOp.FULL) {
                    _items.value = codecVecItem.decode(reader)
                    reader.finish()
                } else if (op == ChangeOp.PATCH) {
                    val ops = KeyedPatch.decodePatch(reader, Item)
                    reader.finish()
                    try {
                        _items.value = KeyedPatch.applyPatch(_items.value, ops)
                    } catch (e: WireException.PatchOutOfBounds) {
                        resync(0u)
                    }
                }
            }
            1u -> {
                if (op == ChangeOp.FULL) {
                    _count.value = Codecs.u32.decode(reader)
                    reader.finish()
                }
            }
            else -> Unit
        }
    }

    /** Re-observes a signal whose mirror diverged from the core, to receive a full value. */
    private fun resync(signalId: UInt) {
        core.observe(handle, signalId, false)
        core.observe(handle, signalId, true)
    }

    companion object {
        /** A list of [`LIST_LEN`] items numbered from 1. */
        fun create(ctx: UndraCore = UndraCore.shared): BigList {
            val handle = ctx.construct(UndraIds.Objects.BigList.TYPE_ID, UndraIds.Objects.BigList.NEW, ByteArray(0))
            return BigList(ctx, handle)
        }
    }
}

/** A counter with a change tally and a computed parity. */
class Counter private constructor(core: UndraCore, handle: Long) : UndraStore(core, handle) {
    private val _count: MutableStateFlow<Int> = signal(0)
    val count: StateFlow<Int> = _count.asStateFlow()
    private val _changes: MutableStateFlow<UInt> = signal(0u)
    val changes: StateFlow<UInt> = _changes.asStateFlow()
    private val _parity: MutableStateFlow<Parity> = signal(Parity.EVEN)
    /** Computed by the core; read-only. */
    val parity: StateFlow<Parity> = _parity.asStateFlow()

    init {
        core.observe(handle, UInt.MAX_VALUE, true)
    }

    /** A counter at zero with no changes made. */
    constructor(ctx: UndraCore = UndraCore.shared) : this(
        ctx,
        ctx.construct(UndraIds.Objects.Counter.TYPE_ID, UndraIds.Objects.Counter.NEW, ByteArray(0)),
    )

    /**
     * Adds `amount` (which may be negative) and counts the change: one transaction, so one
     * change-set for `count`, `changes` and `parity` together. The count saturates instead of
     * overflowing.
     */
    fun add(amount: Int) {
        val w = UndraWriter()
        w.writeI32(amount)
        this.core.callSync(
            CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Counter.ADD),
            UndraIds.Objects.Counter.ADD,
            w.toByteArray(),
        )
    }

    /** Subtracts one. */
    fun decrement() {
        this.core.callSync(
            CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Counter.DECREMENT),
            UndraIds.Objects.Counter.DECREMENT,
            ByteArray(0),
        )
    }

    /** Adds one. */
    fun increment() {
        this.core.callSync(
            CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Counter.INCREMENT),
            UndraIds.Objects.Counter.INCREMENT,
            ByteArray(0),
        )
    }

    /** Sets the count back to zero and forgets the changes, in one transaction. */
    fun reset() {
        this.core.callSync(
            CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Counter.RESET),
            UndraIds.Objects.Counter.RESET,
            ByteArray(0),
        )
    }

    override fun apply(signalId: UInt, op: ChangeOp, reader: UndraReader) {
        when (signalId) {
            0u -> {
                if (op == ChangeOp.FULL) {
                    _count.value = Codecs.i32.decode(reader)
                    reader.finish()
                }
            }
            1u -> {
                if (op == ChangeOp.FULL) {
                    _changes.value = Codecs.u32.decode(reader)
                    reader.finish()
                }
            }
            2u -> {
                if (op == ChangeOp.FULL) {
                    _parity.value = Parity.decode(reader)
                    reader.finish()
                }
            }
            else -> Unit
        }
    }

    companion object {
        /** A counter at zero with no changes made. */
        fun create(ctx: UndraCore = UndraCore.shared): Counter {
            val handle = ctx.construct(UndraIds.Objects.Counter.TYPE_ID, UndraIds.Objects.Counter.NEW, ByteArray(0))
            return Counter(ctx, handle)
        }
    }
}

/**
 * A store that commits many transactions, for the coalesced-delivery scenarios and the
 * playground's stress screen.
 */
class Stress private constructor(core: UndraCore, handle: Long) : UndraStore(core, handle, noCoalesce = setOf(1u)) {
    private val _value: MutableStateFlow<ULong> = signal(0uL)
    val value: StateFlow<ULong> = _value.asStateFlow()
    private val _progress: MutableStateFlow<UInt> = signal(0u)
    val progress: StateFlow<UInt> = _progress.asStateFlow()
    private val _generated: MutableStateFlow<ULong> = signal(0uL)
    val generated: StateFlow<ULong> = _generated.asStateFlow()
    private val _running: MutableStateFlow<Boolean> = signal(false)
    val running: StateFlow<Boolean> = _running.asStateFlow()

    init {
        core.observe(handle, UInt.MAX_VALUE, true)
    }

    /** A store with every signal at its start: zeros, and no generator running. */
    constructor(ctx: UndraCore = UndraCore.shared) : this(
        ctx,
        ctx.construct(UndraIds.Objects.Stress.TYPE_ID, UndraIds.Objects.Stress.NEW, ByteArray(0)),
    )

    /**
     * Commits `transactions` transactions now, each one write of the signal `mode` names: one
     * change-set per transaction, the way data that arrives in the core on its own does.
     */
    fun burst(mode: StressMode, transactions: UInt) {
        val w = UndraWriter()
        StressMode.encode(w, mode)
        w.writeU32(transactions)
        this.core.callSync(
            CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Stress.BURST),
            UndraIds.Objects.Stress.BURST,
            w.toByteArray(),
        )
    }

    /**
     * Starts generating updates of the signal the mode names, at the given number a second,
     * each its own transaction, until `stop`. Called while a generator runs, it retunes that
     * generator (new mode, new rate) instead of starting a second one. Fails, starting
     * nothing, when the rate is zero or above 1,000,000.
     * @throws StressError
     */
    fun start(mode: StressMode, perSecond: UInt) {
        val w = UndraWriter()
        StressMode.encode(w, mode)
        w.writeU32(perSecond)
        try {
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Stress.START),
                UndraIds.Objects.Stress.START,
                w.toByteArray(),
            )
        } catch (e: UndraReplyException) {
            throw StressError.fromReply(e)
        }
    }

    /**
     * Stops the generator: no update is committed after this returns. `generated` keeps its
     * count. Does nothing when no generator runs.
     */
    fun stop() {
        this.core.callSync(
            CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Stress.STOP),
            UndraIds.Objects.Stress.STOP,
            ByteArray(0),
        )
    }

    override fun apply(signalId: UInt, op: ChangeOp, reader: UndraReader) {
        when (signalId) {
            0u -> {
                if (op == ChangeOp.FULL) {
                    _value.value = Codecs.u64.decode(reader)
                    reader.finish()
                }
            }
            1u -> {
                if (op == ChangeOp.FULL) {
                    _progress.value = Codecs.u32.decode(reader)
                    reader.finish()
                }
            }
            2u -> {
                if (op == ChangeOp.FULL) {
                    _generated.value = Codecs.u64.decode(reader)
                    reader.finish()
                }
            }
            3u -> {
                if (op == ChangeOp.FULL) {
                    _running.value = Codecs.bool.decode(reader)
                    reader.finish()
                }
            }
            else -> Unit
        }
    }

    companion object {
        /** A store with every signal at its start: zeros, and no generator running. */
        fun create(ctx: UndraCore = UndraCore.shared): Stress {
            val handle = ctx.construct(UndraIds.Objects.Stress.TYPE_ID, UndraIds.Objects.Stress.NEW, ByteArray(0))
            return Stress(ctx, handle)
        }
    }
}

/** The to-do list: what the UI observes (`todos`, `filter`, `visible`, `remaining`) and calls. */
class Todos private constructor(core: UndraCore, handle: Long) : UndraStore(core, handle) {
    private val _todos: MutableStateFlow<List<Todo>> = signal(emptyList())
    val todos: StateFlow<List<Todo>> = _todos.asStateFlow()
    private val _filter: MutableStateFlow<Filter> = signal(Filter.ALL)
    val filter: StateFlow<Filter> = _filter.asStateFlow()
    private val _visible: MutableStateFlow<List<Todo>> = signal(emptyList())
    /** Computed by the core; read-only. */
    val visible: StateFlow<List<Todo>> = _visible.asStateFlow()
    private val _remaining: MutableStateFlow<UInt> = signal(0u)
    /** Computed by the core; read-only. */
    val remaining: StateFlow<UInt> = _remaining.asStateFlow()

    init {
        core.observe(handle, UInt.MAX_VALUE, true)
    }

    /** An empty list showing every item. */
    constructor(ctx: UndraCore = UndraCore.shared) : this(
        ctx,
        ctx.construct(UndraIds.Objects.Todos.TYPE_ID, UndraIds.Objects.Todos.NEW, ByteArray(0)),
    )

    /**
     * Adds an item at the end of the list.
     * @throws TodoError
     */
    suspend fun add(title: String): Todo {
        val w = UndraWriter()
        w.writeStr(title)
        val body = try {
            this.core.call(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Todos.ADD),
                UndraIds.Objects.Todos.ADD,
                w.toByteArray(),
            )
        } catch (e: UndraReplyException) {
            throw TodoError.fromReply(e)
        }
        return Todo.decodeAll(body)
    }

    /** Removes every finished item. */
    fun clearDone() {
        this.core.callSync(
            CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Todos.CLEAR_DONE),
            UndraIds.Objects.Todos.CLEAR_DONE,
            ByteArray(0),
        )
    }

    /** Removes the item with `id`; unknown ids are ignored. */
    fun remove(id: UUID) {
        val w = UndraWriter()
        Codecs.uuid.encode(w, id)
        this.core.callSync(
            CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Todos.REMOVE),
            UndraIds.Objects.Todos.REMOVE,
            w.toByteArray(),
        )
    }

    /** Chooses which items `visible` holds. */
    fun setFilter(filter: Filter) {
        val w = UndraWriter()
        Filter.encode(w, filter)
        this.core.callSync(
            CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Todos.SET_FILTER),
            UndraIds.Objects.Todos.SET_FILTER,
            w.toByteArray(),
        )
    }

    /** Flips the `done` flag of the item with `id`; unknown ids are ignored. */
    fun toggle(id: UUID) {
        val w = UndraWriter()
        Codecs.uuid.encode(w, id)
        this.core.callSync(
            CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Todos.TOGGLE),
            UndraIds.Objects.Todos.TOGGLE,
            w.toByteArray(),
        )
    }

    override fun apply(signalId: UInt, op: ChangeOp, reader: UndraReader) {
        when (signalId) {
            0u -> {
                if (op == ChangeOp.FULL) {
                    _todos.value = codecVecTodo.decode(reader)
                    reader.finish()
                } else if (op == ChangeOp.PATCH) {
                    val ops = KeyedPatch.decodePatch(reader, Todo)
                    reader.finish()
                    try {
                        _todos.value = KeyedPatch.applyPatch(_todos.value, ops)
                    } catch (e: WireException.PatchOutOfBounds) {
                        resync(0u)
                    }
                }
            }
            1u -> {
                if (op == ChangeOp.FULL) {
                    _filter.value = Filter.decode(reader)
                    reader.finish()
                }
            }
            2u -> {
                if (op == ChangeOp.FULL) {
                    _visible.value = codecVecTodo.decode(reader)
                    reader.finish()
                }
            }
            3u -> {
                if (op == ChangeOp.FULL) {
                    _remaining.value = Codecs.u32.decode(reader)
                    reader.finish()
                }
            }
            else -> Unit
        }
    }

    /** Re-observes a signal whose mirror diverged from the core, to receive a full value. */
    private fun resync(signalId: UInt) {
        core.observe(handle, signalId, false)
        core.observe(handle, signalId, true)
    }

    companion object {
        /** An empty list showing every item. */
        fun create(ctx: UndraCore = UndraCore.shared): Todos {
            val handle = ctx.construct(UndraIds.Objects.Todos.TYPE_ID, UndraIds.Objects.Todos.NEW, ByteArray(0))
            return Todos(ctx, handle)
        }
    }
}

private val codecVecItem = Codecs.vec(Item)
private val codecVecTodo = Codecs.vec(Todo)
